import { PROFILING_KEY } from '../../schemas/index.js';
import { sendErrorResponse, sendStreamErrorResponse } from '../../server/error-handlers.js';
import { PluginHandlerTypeMismatchError } from '../../utils/errors-server.js';
import { setSDKConfig } from '../../server/bare/registry/config-registry.js';
import { setRuntimeContext } from '../../server/bare/registry/runtime-context-registry.js';
import {} from './profiling/index.js';
import { isTerminalChunk } from './rpc-utils.js';
import { createProgressThrottle } from './progress-throttle.js';
import { handlerSupportsProgress, selectHandler } from '../../server/rpc/handler-selection.js';
function getProfilingMetaFromRequest(request) {
    if (PROFILING_KEY in request) {
        return request[PROFILING_KEY];
    }
    return undefined;
}
async function executeReplyHandler(req, request, handler, profiler, isDelegated) {
    profiler.startHandler();
    try {
        let response;
        if (isDelegated) {
            const profilingMeta = getProfilingMetaFromRequest(request);
            response = await handler(request, profilingMeta ? { profilingMeta } : undefined);
        }
        else {
            response = await handler(request);
        }
        profiler.endHandler();
        req.reply(profiler.serialize(response, true), 'utf-8');
    }
    catch (error) {
        profiler.endHandler();
        sendErrorResponse(req, error, profiler);
    }
}
async function executeStreamHandler(req, request, handler, profiler, isDelegated) {
    const stream = req.createResponseStream();
    profiler.startHandler();
    let sentFinalChunk = false;
    try {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        let generator;
        if (isDelegated) {
            const profilingMeta = getProfilingMetaFromRequest(request);
            generator = handler(request, profilingMeta ? { profilingMeta } : undefined);
        }
        else {
            generator = handler(request);
        }
        for await (const response of generator) {
            if (isTerminalChunk(response)) {
                profiler.endHandler();
                stream.write(profiler.serialize(response, true) + '\n', 'utf-8');
                sentFinalChunk = true;
            }
            else {
                stream.write(profiler.serialize(response, false) + '\n', 'utf-8');
            }
        }
        // Fallback
        if (!sentFinalChunk) {
            profiler.endHandler();
            const trailer = profiler.serialize();
            if (trailer) {
                stream.write(trailer + '\n', 'utf-8');
            }
        }
        stream.end();
    }
    catch (error) {
        profiler.endHandler();
        sendStreamErrorResponse(stream, error, profiler);
    }
}
async function executeProgressHandler(req, request, handler, profiler, isDelegated) {
    const stream = req.createResponseStream();
    profiler.startHandler();
    const writeBatch = (updates) => {
        const payload = updates.map((u) => profiler.serialize(u, false)).join('\n');
        stream.write(payload + '\n', 'utf-8');
    };
    const throttle = createProgressThrottle(writeBatch);
    try {
        let response;
        if (isDelegated) {
            const profilingMeta = getProfilingMetaFromRequest(request);
            const options = { progressCallback: throttle.push };
            if (profilingMeta) {
                options.profilingMeta = profilingMeta;
            }
            response = await handler(request, options);
        }
        else {
            response = await handler(request, throttle.push);
        }
        throttle.flush();
        profiler.endHandler();
        stream.write(profiler.serialize(response, true) + '\n', 'utf-8');
        stream.end();
    }
    catch (error) {
        throttle.flush();
        profiler.endHandler();
        sendStreamErrorResponse(stream, error, profiler);
    }
}
export async function executeDuplexHandler(_req, request, entry, inputStream, outputStream, profiler) {
    const { handler } = selectHandler(entry, request);
    profiler.startHandler();
    try {
        for await (const response of handler(request, inputStream)) {
            outputStream.write(profiler.serialize(response, false) + '\n', 'utf-8');
        }
        profiler.endHandler();
        const trailer = profiler.serialize();
        if (trailer) {
            outputStream.write(trailer + '\n', 'utf-8');
        }
        outputStream.end();
    }
    catch (error) {
        profiler.endHandler();
        sendStreamErrorResponse(outputStream, error, profiler);
    }
}
// Unified handler executor with delegation and progress support
export async function executeHandler(req, request, entry, profiler) {
    const { handler, isDelegated } = selectHandler(entry, request);
    const wantsProgress = handlerSupportsProgress(entry, request);
    if (entry.type === 'duplex') {
        throw new PluginHandlerTypeMismatchError(request.type, 'reply or stream', 'duplex');
    }
    if (entry.type === 'stream') {
        await executeStreamHandler(req, request, handler, profiler, isDelegated);
    }
    else if (wantsProgress) {
        await executeProgressHandler(req, request, handler, profiler, isDelegated);
    }
    else {
        await executeReplyHandler(req, request, handler, profiler, isDelegated);
    }
}
export function isInitConfigMessage(data) {
    return (typeof data === 'object' && data !== null && 'type' in data && data.type === '__init_config');
}
export function handleInitConfig(req, data) {
    try {
        if (data.config) {
            setSDKConfig(data.config);
        }
        if (data.runtimeContext) {
            setRuntimeContext(data.runtimeContext);
        }
        req.reply(JSON.stringify({ success: true }), 'utf-8');
    }
    catch (error) {
        req.reply(JSON.stringify({
            success: false,
            error: error instanceof Error ? error.message : String(error)
        }), 'utf-8');
    }
}
export function isShutdownMessage(data) {
    return (typeof data === 'object' &&
        data !== null &&
        'type' in data &&
        data.type === '__shutdown__');
}
export async function handleShutdown(req) {
    try {
        // Lazy import to avoid the import cycle:
        //   handler-utils -> worker-core -> create-server -> handle-request
        //   -> handler-utils. By the time this runs, all modules are loaded.
        const { cleanupForTerminate } = await import('../../server/worker-core.js');
        await cleanupForTerminate();
        req.reply(JSON.stringify({ success: true }), 'utf-8');
    }
    catch (error) {
        req.reply(JSON.stringify({
            success: false,
            error: error instanceof Error ? error.message : String(error)
        }), 'utf-8');
    }
}
